CREATE TABLE `coupons` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `code` VARCHAR(40) NOT NULL, `discount_type` ENUM('FIXED', 'PERCENTAGE') NOT NULL, `discount_value` INT UNSIGNED NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `valid_from` DATETIME(3) NULL, `valid_until` DATETIME(3) NULL, `max_uses` INT UNSIGNED NULL, `max_uses_per_customer` INT UNSIGNED NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `coupons_public_id_key` (`public_id`), UNIQUE INDEX `coupons_tenant_id_code_key` (`tenant_id`, `code`), INDEX `coupons_tenant_id_active_idx` (`tenant_id`, `active`), CONSTRAINT `coupons_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `coupon_redemptions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `coupon_id` BIGINT UNSIGNED NOT NULL, `appointment_id` BIGINT UNSIGNED NOT NULL, `customer_id` BIGINT UNSIGNED NOT NULL, `discount_amount_cents` BIGINT UNSIGNED NOT NULL, `canceled_at` DATETIME(3) NULL, `canceled_reason` VARCHAR(500) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `coupon_redemptions_public_id_key` (`public_id`), UNIQUE INDEX `coupon_redemptions_coupon_id_appointment_id_key` (`coupon_id`, `appointment_id`), INDEX `coupon_redemptions_tenant_id_coupon_id_customer_id_idx` (`tenant_id`, `coupon_id`, `customer_id`), INDEX `coupon_redemptions_tenant_id_appointment_id_idx` (`tenant_id`, `appointment_id`), CONSTRAINT `coupon_redemptions_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `coupon_redemptions_coupon_id_fkey` FOREIGN KEY (`coupon_id`) REFERENCES `coupons`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `coupon_redemptions_appointment_id_fkey` FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `coupon_redemptions_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
